class Solution { public List<String> summaryRanges(int[] nums){List<String> answer=new ArrayList<>();for(int start=0;start<nums.length;){int end=start;while(end+1<nums.length&&(long)nums[end+1]-nums[end]==1)end++;answer.add(start==end?String.valueOf(nums[start]):nums[start]+"->"+nums[end]);start=end+1;}return answer;} }
